    result = [row[:] for row in grid]

    # Find structure points (sparse diagonal points: 5s in this input)
    struct_pts = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 5]

    if not struct_pts:
        return result

    # Determine structure line type and constant
    # Check if SE diagonal (r-c = const) or SW diagonal (r+c = const)
    if struct_pts[1][0] - struct_pts[0][0] == struct_pts[1][1] - struct_pts[0][1]:
        # SE diagonal: r - c = const
        line_const = struct_pts[0][0] - struct_pts[0][1]
    else:
        # SW diagonal: r + c = const
        line_const = struct_pts[0][0] + struct_pts[0][1]

    # Find wall columns
    wall_color = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 9 and grid[r][c] != 5:  # Different from background 9 and structure 5
                wall_color = grid[r][c]
                break
        if wall_color:
            break

    if not wall_color:
        return result

    # Find which columns contain wall cells
    wall_cols = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == wall_color:
                wall_cols.add(c)

    wall_cols_list = sorted(wall_cols)

    # Place 3s at wall column positions where structure line passes
    for c in wall_cols_list:
        if line_const == struct_pts[0][0] - struct_pts[0][1]:  # SE line (r-c = const)
            r = c + line_const
        else:  # SW line (r+c = const)
            r = line_const - c

        if 0 <= r < rows and 0 <= c < cols:
            if result[r][c] == wall_color:
